// Embedded into the portable report. No network requests, model or external assets.
const HELP = {};
const CONTEXT_HELP = {};
const HELP_TOPICS = typeof BH_HELP_CATALOG==='undefined'?[]:BH_HELP_CATALOG.Topics||[];
function helpTopicForField(key){return HELP_TOPICS.find(t=>(t.Fields||[]).some(f=>f.toLowerCase()===String(key).toLowerCase()));}
function explainHelpTopic(topic){
 const root=activateHelper(topic.Title);root.append(helpText('p',topic.Summary));
 for(const section of topic.Sections||[])helpSection(root,section.Title,section.Text);
 if(topic.Fields?.length)helpSection(root,'Related properties',topic.Fields.join(', '));
}
function explainProperty(key,node){
 const topic=helpTopicForField(key);
 if(topic)explainHelpTopic(topic);else{const root=activateHelper('Property: '+key);helpSection(root,'Interpretation unavailable','This field has no built-in interpretation. Inspect its source and collection notes; do not infer effective access from an unfamiliar value.');}
 if(node){const back=helpText('button','Back to '+(node.n||node.i));back.type='button';back.addEventListener('click',()=>explainNode(node));document.getElementById('helperContent').append(back);}
}function searchHelp(query){
 const words=String(query||'').trim().toLowerCase().split(/\s+/).filter(Boolean);
 const entries=HELP_TOPICS.map(t=>({label:t.Category+' · '+t.Title,search:[t.Key,t.Category,t.Title,t.Summary,t.Terms,...(t.Fields||[]),...(t.Sections||[]).map(s=>s.Title+' '+s.Text)].join(' '),topic:t}));
 for(const [type,h] of Object.entries(HELP))entries.push({label:'Relationships · '+type+' · '+h.title,search:[type,h.title,h.meaning,h.why,h.impact,h.check,h.caveat].join(' '),type});
 return entries.filter(e=>words.every(w=>e.search.toLowerCase().includes(w))).sort((a,b)=>a.label.localeCompare(b.label));
}
function defineContextHelp(types,kinds,meaning,prerequisites,action,validation,caution){
 for(const type of types.split('|'))for(const kind of kinds.split('|'))CONTEXT_HELP[type+'|'+kind]={meaning,prerequisites,action,validation,caution};
}
function relationshipContext(edge){
 let kind=edge.tt||edge.tk;
 if(!kind){const node=[...(DATA.Analysis?.Objects||[]),...(DATA.Ego?.Nodes||[])].find(n=>String(n.i).toLowerCase()===String(edge.t).toLowerCase());kind=node?.t;}
 return CONTEXT_HELP[edge.ty+'|'+kind]||null;
}
function ownershipProof(edge){try{const proof=typeof edge.Evidence==='string'?JSON.parse(edge.Evidence):edge.Evidence;return proof&&['OwnershipControlV1','OwnershipLegacyV1'].includes(proof.Derivation)?proof:null;}catch{return null;}}
function relationshipMeaning(edge){if(ownershipProof(edge)?.Assessment==='Suppressed projection')return 'Ownership evidence was retained, but automatic control-path projection was suppressed. This row does not establish control.';return relationshipContext(edge)?.meaning||HELP[edge.ty]?.meaning||'Recorded relationship; verify its source documentation.';}
defineContextHelp('GenericAll|GenericWrite','groups','Control of group properties can include changing membership, making the group and its downstream permissions the focus of review.','Verify the exact write-member rights, deny rules, group type and nested memberships. A distribution group does not supply a security token.','Replace unnecessary group-wide writes with the membership-management delegation required by the approved provisioning role.','Rescan the group ACL and nested paths, then test the approved membership-management workflow.','Removing a group-management delegation can interrupt provisioning; changing group membership can remove access to many resources.');
defineContextHelp('GenericAll','users','Broad control of a user object may expose password-reset or credential-related changes, subject to protections and the actual effective rights.','Identify whether this is a person or service account and verify the relevant reset, credential and ownership rights.','Replace unnecessary user-object full control with narrowly scoped support or service-management permissions.','Rescan the user ACL and alternative group grants, then test the legitimate support or service workflow.','Avoid resetting a password merely to remove an ACL grant; credential changes can interrupt services and affect access to protected data.');
defineContextHelp('GenericWrite','users','Property-write access on a user can affect attributes such as service names or key credentials. It is not itself a password-reset permission.','Check which attributes are writable, the required authentication infrastructure and protections on this account.','Delegate only the user attributes required by the service-management role instead of broad property writes.','Rescan the attribute permissions and confirm that approved service names and enrollment workflows still work.','Removing required service-name or enrollment delegation can interrupt authentication or device enrollment.');
defineContextHelp('GenericAll|GenericWrite','computers','These are rights on a computer account in the directory. They are separate from proven local-administrator access to the running endpoint.','Verify the writable account attributes, delegation configuration, credential prerequisites and the actual endpoint authorization.','Narrow computer-account delegation to the required provisioning attributes and review unauthorized delegation or key-credential writers.','Rescan the directory ACL and delegation settings, then test domain join and the approved device-management workflow.','Changing computer-account delegation or credentials can interrupt domain trust and service authentication.');
defineContextHelp('GenericAll|GenericWrite|WriteDacl','gpos','The observation concerns the directory portion of a GPO. File permissions and policy applicability also determine its practical effect.','Check both the directory object and SYSVOL permissions, policy links, security filtering, enforcement and inheritance.','Restrict GPO editing and permission management to the approved policy-management role; review the directory and SYSVOL permissions together.','Compare both permission sets and confirm the expected policy applies to a representative authorized user or computer.','A policy or SYSVOL change can affect many machines. Preserve the prior policy and permission settings before an approved change.');
defineContextHelp('GenericAll|GenericWrite','ous','Rights on a container do not automatically establish control of every child object. Inheritance and policy links require separate evaluation.','Confirm the actual object class and identify which applicable ACEs are inherited by which children.','Narrow unnecessary container-level delegation at its originating scope, preserving required child-object management.','Rescan the container and representative children; test the approved delegated administration workflow.','Changing an inherited container grant can affect many child objects; avoid deleting unrelated explicit permissions.');
defineContextHelp('DCSync','domains','This is a replication capability candidate on one domain, supported by paired grants or an explicit source observation.','Verify both replication rights on this domain, each grant trustee, membership witnesses and full-token deny behavior.','Remove or narrow the unauthorized prerequisite grant or membership at its actual source; preserve approved replication services.','Rescan both grants and all relevant memberships. Confirm the candidate and alternative routes are absent while approved replication remains healthy.','Do not remove required domain-controller or synchronization permissions. Changing a shared group can affect other delegated services.');
defineContextHelp('GenericAll|WriteDacl','domains','Control of the domain-root object or its permission list can affect domain-wide delegation and needs review at the domain boundary.','Verify the effective object-control grant and review replication permissions separately, including trustees, group paths and denies.','Narrow unauthorized domain-root full control or permission-management delegation while preserving approved directory-service roles.','Rescan the domain-root ACL and replication prerequisites, check alternative grants, and confirm directory services remain healthy.','Domain-root permission changes can disrupt replication and delegated services; preserve the original ACL and approved service grants.');
defineContextHelp('CanRDP','computers','The relationship represents potential Remote Desktop access; it does not establish local-administrator access or privileged execution.','Check Remote Desktop authorization, logon allow and deny policy, service availability, firewall reachability and authentication requirements.','Remove unnecessary Remote Desktop authorization at the responsible local-group or policy assignment.','Rescan the assignment and validate allowed support access using the approved endpoint-management process.','Removing a shared remote-support assignment can lock out legitimate operators.');
defineContextHelp('HasSession','users','The target user had a recorded session on the source computer. This is time-sensitive evidence, not a reusable permission grant.','Check when the session was observed and whether it is still active. A session does not prove credentials remain available.','Coordinate ending an unneeded privileged session and separate privileged administration from lower-trust hosts.','Collect comparable session data again and verify the approved administration workflow; a single absent session does not prove a lasting fix.','Signing out a user can interrupt work. Session observations can change without any permission change.');
defineContextHelp('WriteGPLink','ous|domains|sites','Editing policy links can alter policy scope, but the effect depends on the linked policy and which users or computers actually receive it.','Verify linked GPO control, filtering, enforcement, inheritance and the affected objects; site scope also depends on site and subnet configuration.','Restrict link editing to the approved policy-management role and remove unauthorized links only after reviewing their scope.','Review the remaining links and validate effective policy on representative affected users or computers.','Changing a link can remove legitimate security or service settings across an entire policy scope.');
defineContextHelp('WriteAccountRestrictions','users|computers','This records a property-set write grant. The attributes and account-control changes permitted in practice depend on target type and directory checks.','Inspect the property-set members and additional rights required for each proposed account or delegation change.','Delegate only the individual account-restriction attributes required by the approved provisioning workflow.','Rescan the exact attribute permissions and test the intended provisioning workflow without changing unrelated account controls.','Do not infer account takeover or replace all account-control settings from this observation alone.');
function defineHelp(types, title, meaning, why, impact, check, caveat, category='review') {
  for (const type of types.split('|')) HELP[type] = {title,meaning,why,impact,check,caveat,category};
}
defineHelp('ADCSESC1','Certificate enrollment identity candidate','The same principal has modeled enrollment capabilities on an eligible template and its publishing CA.','Imported evidence supports subject-supplied authentication certificates without approval or applicable signatures, plus direct-root/NTAuth trust and an enabled same-domain CA host.','Enrollment may permit an identity-bearing authentication certificate, subject to effective access and current server enforcement.','Review the exact template, publishing CA, separate enrollment grant witnesses, root and NTAuth objects, and host. Confirm the approved identity and enrollment workflow before changing permissions.','Supported scope is imported direct-root CAs only. This is not verified certificate issuance, exploitation or a guarantee of current authentication behavior.');
defineContextHelp('ADCSESC1','domains','An enrollment capability candidate reaches this domain through imported template and CA evidence.','Validate the same principal/token on both enrollment branches, the exact publishing CA, direct-root and NTAuth trust, host state and current authentication enforcement.','Review whether requester-supplied identities are required, narrow unauthorized enrollment grants, and consider approval or signature controls that preserve legitimate enrollment.','Rescan the template and CA service permissions and trust data. Confirm the candidate is removed and approved certificate enrollment and renewal still work.','CA/template changes can disrupt authentication, auto-enrollment and renewal; preserve the original configuration and coordinate with the PKI owner.');
defineHelp('GPOAppliesTo','Computer policy scope candidate','Collected directory evidence places this computer in the enabled GPO link scope, with supported Read and Apply grants.','The model checked link enforcement, blocked inheritance, a unique DN-consistent containment chain, known security-enabled group memberships and the GPO computer-policy flags.','Control of the GPO may affect this computer if policy content can also be changed and the client processes it. This is a review candidate.','Review the recorded link root, containment chain, Read/Apply membership witnesses and GPO ACL. Separately verify SYSVOL write access, client processing, extensions and actual resultant policy. Remove unnecessary GPO edit or link permissions only through normal change control.','This is not an observed policy execution or confirmed administrative access. WMI-filtered GPOs, relevant denies, unsupported ACLs, missing metadata and conflicting snapshots suppress this inference. User, site and loopback policy are not derived.','context');
defineHelp('ReplicationAnalysisBlocked','Replication inference requires review','A native domain ACL contains a replication-related deny or an unsupported applicable ACE.','The collector recorded a conservative stop marker for membership-based DCSync inference.','The automatic permission intersection is skipped for this domain.','Review the original domain ACL and full effective token before assessing replication capability.','This marker does not prove that replication is denied for every principal. Existing direct grants remain separate observations.','context');
defineHelp('HasIssuancePolicy|OIDGroupLink','Certificate-policy association','The directory records a template policy OID or an issuance-policy group link.','The relevant policy OID or group-link attribute was collected.','The association supplies context for certificate-policy review.','Review template publication, policy OIDs, linked groups and authentication prerequisites together.','This association alone grants no group membership and is not traversed as a privilege path.','context');
defineHelp('HostsSiteServer|SiteServerOf|InSite','Directory site association','The directory links a server or subnet to its site inventory.','A server-reference, parent-site or subnet-site attribute was collected.','Site information helps explain directory topology and administrative scope.','Verify the referenced computer, site and subnet configuration with the directory owner.','This is topology inventory, not an observed login, endpoint connection or privilege grant.','context');
defineHelp('GenericAll','Full control','The source has broad control over the target directory object.','The dataset contains a GenericAll permission from the source to this target.','Control of an account, group, computer or policy can extend access to other resources. The effect depends on the target type.','Confirm the business owner and intended delegation. Review the target ACL, including inheritance, and remove unnecessary full-control grants.','A collected allow right approximates effective access; group tokens, deny entries and object protections still need checking.');
defineHelp('GenericWrite','Write object properties','The source can change a broad set of properties on the target object.','A GenericWrite grant was recorded on the target.','Changing security-sensitive properties may create additional access, depending on the target.','Inspect the target type and delegated attributes. Replace broad write access with the specific permissions the role needs.','This does not mean the source can change every protected attribute or immediately take over the target.');
defineHelp('WriteDacl','Change permissions','The source can change the permission list on the target.','A WriteDacl grant was recorded.','Someone controlling the source could grant additional access to the target.','Inspect who can edit this ACL and why. Remove unnecessary permission-management rights and check inheritance.','Confirm effective rights and protected-object behavior before deciding the grant is exploitable.');
defineHelp('OwnsRaw|WriteOwnerRaw|OwnsLimitedRights|WriteOwnerLimitedRights','Raw or limited ownership evidence','The dataset records ownership or an ownership-related permission.','Raw evidence is kept separately from derived control paths.','This inventory row alone does not establish DACL-edit access.','Inspect OWNER RIGHTS, explicit WRITE_DAC, the directory policy and server behavior. Check the derived assessment and any conflicting snapshots.','Raw and limited observations are not automatically traversed as full object control.','context');
defineHelp('ForceChangePassword','Reset another account’s password','The source has a password-reset right over the target account.','A ForceChangePassword grant was recorded.','An unnecessary reset delegation can allow someone to take control of another account.','Confirm the helpdesk or service delegation and its scope. Limit reset rights to the required accounts.','This is a permission observation, not evidence that any password was changed.');
defineHelp('DCSync','Directory replication rights','The dataset records a DCSync capability candidate on this domain.','Paired direct grants were collected, or both prerequisite grants were inferred through recorded group memberships.','Unnecessary replication permissions can expose domain credential material.','Confirm this is a domain controller or an approved replication service. Review both domain-root replication grants, membership witnesses and deny rules.','A direct allow or inferred relationship does not establish full-token effective access or successful credential replication.');
defineHelp('AllExtendedRights','Broad extended rights','The source has broad extended rights on the target.','An AllExtendedRights grant was recorded.','The available actions depend on the target, and can include sensitive account or domain operations.','Inspect the target’s extended rights and the business reason for the delegation. Prefer narrowly scoped rights.','Do not infer a particular attack from this label without checking the target and prerequisites. Grants on groups and other non-account objects are inventory only and do not imply group-membership control.');
defineHelp('AdminTo','Local administrator access','The source is represented as an administrator of the target computer.','Native local-group collection or an imported dataset recorded an administrator relationship.','Control of the source may give administrative control of that computer and access to sensitive data.','Check the computer’s local Administrators group, nested memberships, device tier and intended support role.','Actual remote access also depends on policies, token filtering, credentials and network reachability.');
defineHelp('CanRDP','Remote desktop membership','The source has a recorded relationship associated with Remote Desktop access to the target.','Endpoint group enumeration or an imported dataset recorded CanRDP.','Remote interactive access may expose applications and data on the computer.','Review Remote Desktop Users, logon allow/deny policies, MFA and network restrictions.','Group membership alone does not prove that a remote desktop logon will succeed.');
defineHelp('HasSession','A user was observed logged on','The target user was reported as logged on to the source computer at collection time.','Endpoint enumeration or the imported data contained a session observation.','A privileged user on a lower-trust computer may increase exposure if that computer is compromised.','Confirm the session is current, check administrative logon practices, and separate privileged accounts from routine workstation use.','This can become stale quickly. It does not prove credentials are recoverable or that the user is still connected.');
defineHelp('AllowedToAct','Resource-based delegation','The target computer’s delegation descriptor names the source as allowed to act on behalf of users.','The collector read the target’s resource-based delegation security descriptor.','Control of an allowed source account can permit impersonation to the target under suitable conditions.','Confirm the service dependency and approved delegating accounts. Review the target’s delegation descriptor.','User protections, protocol behavior and credentials affect the result; the relationship alone is not a successful impersonation.');
defineHelp('AllowedToDelegate','Constrained delegation','The source account has an allowed service target that resolves to this collected object.','An allowed-to-delegate SPN was resolved against the dataset’s service names.','Control of a delegation account may allow impersonation to the named service under suitable conditions.','Review the exact allowed services, protocol-transition setting, account ownership and protected-user policy.','An SPN-to-object link identifies a potential target. It does not prove every service on the computer is reachable or delegation will succeed.');
defineHelp('HasSIDHistory','Historical identity on an account','The source account contains the target SID in its SID history.','The collector read the account’s sIDHistory attribute.','Historical SIDs can retain access from an older identity or migration.','Confirm the migration purpose, expected history and remaining permissions. Remove obsolete history through an approved change.','Trust filtering and token behavior affect whether a historical SID grants access.');
defineHelp('AddAllowedToAct','Change a computer’s delegation permissions','The source has a recorded write permission on the target computer’s resource-based delegation descriptor.','A write-property ACE for msDS-AllowedToActOnBehalfOfOtherIdentity was recorded.','An unauthorized change could permit another identity to delegate to this computer when the required authentication conditions hold.','Review the provisioning role, exact ACE, deny rules and target protections. Remove unnecessary writes to this attribute.','This is permission to change the descriptor, not evidence that delegation is configured or that an identity can currently delegate.');
defineHelp('WriteAccountRestrictions','Change account restrictions','The source has a recorded write-property permission on the target account’s Account Restrictions property set.','A write-property ACE for property-set GUID 4c164200-20c0-11d0-a768-00aa006e0529 was recorded.','Changing writable account-restriction properties can affect account security when the required directory checks permit it.','Review the property-set members in this forest, deny rules, target protections and intended provisioning role. Delegate only the required individual properties where practical.','This does not establish that every property or account-control bit is writable, that delegation is configured, or that an account can be taken over. Full-token effective access still needs validation.');
defineHelp('AddKeyCredentialLink','Change key credentials','The source can change key-credential data associated with the target.','The dataset includes an AddKeyCredentialLink relationship.','An unauthorized credential change could create another way to authenticate as the target.','Review who can write key credentials, legitimate enrollment requirements, and recent credential changes.','Authentication infrastructure and target-specific prerequisites still apply.');
defineHelp('WriteSPN','Change service names','The source can change service principal names on the target account.','A WriteSPN relationship was recorded.','Service-name changes can affect authentication and create credential-exposure opportunities.','Confirm who manages this service account and which SPNs it requires. Restrict unauthorized SPN changes.','Target properties and authentication prerequisites determine the practical risk.');
defineHelp('WriteGPLink','Change policy links','The source can change Group Policy links on the target.','A WriteGPLink relationship was recorded.','Changing policy links may change which settings apply to users or computers in scope.','Review policy-link delegation, linked policies, enforcement, filtering and affected objects.','Link-edit rights do not by themselves grant control of a policy or guarantee its application.');
defineHelp('SQLAdmin','Database administration','The dataset represents administrative rights on a SQL Server target.','An imported or collected SQLAdmin relationship was present.','Administrative database access may expose data and sensitive service configuration.','Validate the SQL role, business owner, service identity and least-privilege configuration.','The relationship does not prove operating-system administration or successful connection.');
defineHelp('MemberOf','Group membership','The source is a member of the target group.','Direct or primary group membership was recorded.','The source may receive permissions assigned to this group. Membership is normal directory behavior.','Check whether membership is intended and whether the group grants sensitive access.','Nested groups and token behavior affect effective access. This is context, not a vulnerability by itself.','context');
defineHelp('Contains','Directory location','The source container contains the target object.','The directory object’s parent was recorded.','Location helps explain policy and inherited permissions.','Review the organizational structure and inheritance when investigating another permission.','Containment alone does not grant control.','context');
defineHelp('GPLink','Group Policy link configuration','A policy-link configuration references the target site, domain or organizational unit.','A Group Policy link was recorded; inspect its enabled/enforced metadata.','An enabled link may affect objects in scope; a disabled link is inventory only.','Review security filtering, inheritance, enforcement and policy settings.','A link alone does not prove application. Missing metadata is not evidence that a link is enabled.','context');
defineHelp('PublishedTo','Template publication','The certificate template is published on the target certificate authority.','The authority’s certificateTemplates list referenced this template.','Publication helps establish where a template can be requested.','Review the template alongside the authority’s issuance and enrollment controls.','Publication alone does not establish an unsafe certificate configuration.','context');
defineHelp('TrustRelationship','Domain trust inventory','The collected domain has a recorded trust relationship with the remote domain.','A trustedDomain object was found in the directory.','Trust configuration affects cross-domain authentication boundaries.','Review direction, attributes, SID filtering, selective authentication and the business purpose.','This inventory link does not describe attack direction or prove cross-domain escalation.','context');
defineHelp('WriteOwner','Change an object owner','The source has a recorded permission to change the owner of the target directory object.','The ACL or imported record contains WriteOwner; the ownership model checks supported OWNER RIGHTS and captured policy context.','A new owner may obtain additional permission-management capability when the applicable server policy and descriptor permit it.','Inspect the projected assessment, target class, owner restrictions, relevant denies and captured policy before reviewing the unnecessary owner-change grant.','Changing an owner does not unconditionally grant every permission. Computer/MSA/gMSA restrictions and unsupported server behavior can suppress or qualify the projection.');
defineHelp('Owns','Recorded ownership capability','The source is the recorded owner of the target object, with modeled owner rights assessed separately.','Ownership was captured in the descriptor or imported record; raw observations and projected control are kept distinct.','An owner can sometimes manage the object DACL, subject to OWNER RIGHTS, relevant denies and supported server-policy exceptions.','Confirm the intended owner and inspect the assessment and original descriptor. Correct unauthorized ownership and unnecessary owner-related delegation through normal change control.','The owner is not necessarily an administrator of a computer endpoint. A raw owner observation, conditional legacy edge or suppressed projection is not verified effective access.');
defineHelp('GetChanges','Replicate directory changes','The source has one recorded domain replication prerequisite for directory changes.','The domain ACL or imported source reports the GetChanges extended right.','Combined with GetChangesAll on the same domain and an intersecting principal/token, this may support a modeled DCSync candidate.','Inspect both separate grants, their trustees, membership witnesses, domain identity and relevant deny context.','GetChanges alone is not modeled as DCSync and does not establish access to password-related replication data.','context');
defineHelp('GetChangesAll','Replicate sensitive directory changes','The source has the recorded GetChangesAll replication prerequisite on a domain.','The domain ACL or imported source reports this extended right.','The model combines this with GetChanges on the same domain when both reach the same principal through supported memberships.','Review the paired prerequisite and membership witnesses; distinguish an explicit source grant from a derived intersection.','A single prerequisite, unknown token context or incomplete domain ACL does not establish a usable DCSync operation.','context');
defineHelp('AddMember','Manage group membership','The source has a modeled capability to change the membership of the target group.','An applicable membership write or imported AddMember observation was recorded.','Adding another principal to a security group can give that principal the permissions and memberships carried by the group.','Check the exact member-attribute grant, inherited source, security-enabled group state, token restrictions and intended provisioning delegation.','This is not proof that membership was changed. Distribution groups, protected targets, denies and directory checks can affect the practical result.');
defineHelp('AddSelf','Add self to a group','The source has a recorded self-membership capability on the target group.','The ACL or imported record identifies the self-membership right rather than general membership management.','The source may be able to place its own identity into a security group and obtain group-derived capabilities.','Verify the self-membership right, actual trustee and target group; narrow only the unnecessary delegation.','AddSelf is narrower than adding arbitrary accounts. Effective token, target protections and directory checks remain prerequisites.');
defineHelp('CanPSRemote','Potential PowerShell remoting access','The source has a recorded remote-management authorization or relevant group assignment on the target computer.','Endpoint or supported imported collection recorded the assignment.','The principal may be able to use a permitted remoting endpoint if the service, network, authentication and endpoint configuration allow it.','Check the exact WinRM/PowerShell endpoint authorization, local and policy assignments, service availability and intended management role.','Remote-management membership alone does not prove local administrator access, access to every remoting endpoint or successful execution.');
defineHelp('ExecuteDCOM','Potential DCOM access','The source has a recorded DCOM-related authorization or group assignment on the target computer.','Endpoint or imported collection recorded a relevant DCOM membership or permission.','Some applications may permit remote activation or execution when application-specific launch, access and authentication conditions hold.','Review application-specific DCOM launch/access permissions, the relevant service, network reachability and the approved support role.','A DCOM group assignment is not a guarantee that a particular application can be activated or that execution is privileged.');
defineHelp('ReadLAPSPassword','Potential LAPS password read','The source has a recorded capability related to reading a managed local administrator password for this computer.','Supported directory ACL or imported evidence reports the password-read capability.','An authorized reader may obtain access to the managed local account, subject to the deployment and authentication controls.','Identify legacy versus Windows LAPS, the managed account, exact readable attribute, encryption/decryptor authorization and current rotation policy.','No password value was collected by this viewer. Modern encrypted LAPS can require additional decryption rights; a read-related observation alone does not prove usable administrator access.');
defineHelp('ReadGMSAPassword','Potential gMSA managed-password read','The source is recorded as a permitted reader in the supported managed-service account password-reader model.','Native collection evaluates the embedded msDS-GroupMSAMembership descriptor or the importer supplies a supported observation.','A principal able to retrieve the managed secret may act as the gMSA where that service identity is authorized.','Review the gMSA reader descriptor, security-group memberships, intended service hosts and the account downstream rights.','This is a modeled permission, not a collected secret. A normal account ACL alone is not sufficient native evidence, and full-token conditions still require validation.');
defineHelp('DumpSMSAPassword','Potential standalone MSA secret access','The source host or principal has a recorded relationship to obtaining a standalone managed service account secret.','Supported imported collection reports the MSA-specific capability.','Access to an assigned managed service identity can affect the services and resources authorized to that account.','Confirm the managed account class, assigned host, source identity, actual collection provenance and intended service deployment.','Standalone MSA and gMSA reader mechanisms differ. The relationship does not mean Tessera retrieved a password or that every host can obtain the secret.');
defineHelp('Enroll','Certificate enrollment observation','The source has a recorded enrollment-related allow observation on a certificate template or CA object.','Directory or imported ACL data contains an Enroll classification.','The observation can be a prerequisite for certificate issuance when the template, publication and actual CA-service rights also qualify.','Identify the target class and evidence source. For ESC1, inspect both the template and the same publishing CA service grant.','Directory-object Enroll is inventory and cannot substitute for successful CA-service permission collection. Enrollment alone is not a domain takeover or an issued certificate.','context');
defineHelp('AutoEnroll','Certificate auto-enrollment observation','The source has a recorded auto-enrollment-related permission on a certificate template.','The template ACL or imported record contains AutoEnroll.','The permission can participate in an approved automatic certificate enrollment workflow when policy, enrollment rights and issuance prerequisites permit it.','Review template Enroll and AutoEnroll permissions, policy applicability, publication, CA-service authorization and actual enrollment behavior.','AutoEnroll is not a substitute for the required enrollment permissions, and its presence alone is not an ESC1 or privilege-path derivation.','context');
defineHelp('ManageCA','Unverified CA-management observation','A ManageCA-related observation is associated with the CA directory object or supplied source.','Native collection can classify related directory masks; imported summaries must be checked for their actual permission authority.','Actual CA-service management authority can affect CA configuration, but directory and service permissions can differ.','Review the original evidence authority and actual CA-service descriptor before deciding whether the principal can change CA configuration.','The observation is inventory and excluded from automatic management-control paths. It is not proof of CA-service administration or certificate issuance.','context');
