defineContextHelp('ReadLAPSPassword','computers','This is a managed local-account secret-read candidate for a computer.','Identify the LAPS deployment, exact attributes, encryption/decryptor controls, managed account and current password validity.','Limit password readers/decryptors to approved support roles, then follow the managed rotation process after a confirmed exposure.','Recollect readers and test approved recovery access and rotation without embedding password values in the report.','Deleting all recovery access or rotating an account without considering dependencies can interrupt support.');
defineContextHelp('ReadGMSAPassword|DumpSMSAPassword','users','This concerns a managed service identity whose downstream privileges may be more important than its account name.','Confirm MSA versus gMSA, the host/reader mechanism, effective token, approved service hosts and downstream authorizations.','Narrow the unnecessary reader/host relationship and review the service identity privileges with the service owner.','Rescan the relevant descriptor or host relationship and confirm approved services can still obtain credentials and run.','Do not remove intended reader hosts or manipulate managed credentials without considering service continuity.');
defineContextHelp('AddMember|AddSelf','groups','Changing security-group membership can give a new member the privileges carried by this group.','Distinguish arbitrary membership management from self-membership, validate security-enabled state and review nested memberships and exact ACL scope.','Narrow unauthorized member-attribute or self-membership delegation at its actual source.','Rescan the group and nested paths and confirm the approved provisioning process still functions.','Changing a shared group or inherited delegation may affect many users and services.');
defineContextHelp('AllowedToAct|AddAllowedToAct','computers','Resource-based delegation is controlled by the target service computer descriptor; permission to edit it is distinct from a configured allowed principal.','Identify whether the edge records existing descriptor contents or a write capability, then validate source credentials, target protections and authentication prerequisites.','Remove unauthorized existing delegation or unnecessary descriptor writers at the actual target configuration or originating ACL.','Recollect both the descriptor and its writers, inspect alternative grants and test the approved service-authentication workflow.','Changing delegation can break applications that legitimately impersonate users to this service.');
defineContextHelp('AllowedToDelegate','computers','The source account is configured for constrained delegation to a service associated with this computer.','Inspect the exact allowed SPNs, host resolution, protocol-transition setting, user sensitivity and current authentication conditions.','Remove obsolete service targets and restrict delegation to the exact approved service identities and destinations.','Recollect delegation and SPN resolution and test approved service authentication to each retained target.','A host-level graph edge abstracts specific services; not every service on that computer is necessarily authorized.');
defineContextHelp('WriteSPN|AddKeyCredentialLink','users|computers','These are writes to specific credential- or service-related attributes on the directory account.','Validate the exact attribute right, current values, account class, supported authentication infrastructure and directory protections.','Restrict these attributes to the approved provisioning/enrollment role and review existing values with the account owner.','Rescan attribute grants and values and confirm legitimate enrollment and service-name management still work.','Removing legitimate service names or key credentials can interrupt authentication; a write grant is not evidence a credential was added.');
defineContextHelp('WriteDacl','users|computers|groups','The source can potentially modify permissions on this directory object; downstream effects depend on the rights it could validly grant.','Inspect the actual applicable WRITE_DAC grant, inherited source, deny context, protected-object behavior and target type.','Narrow unnecessary DACL-edit delegation at the originating ACL while preserving approved administration.','Rescan the same scope, recollect the descriptor and all equivalent grants, and test the intended account/group/device management workflow.','Changing an inherited ACL can affect many descendants. Permission management on a computer object is separate from endpoint administration.');
defineContextHelp('GenericAll|GenericWrite|WriteDacl|WriteOwner|Owns','certtemplates|enterprisecas','This concerns control of a PKI directory object; practical certificate consequences require separate template and CA-service prerequisites.','Review the exact target class, writable properties, ownership assessment, publication, actual service permissions, trust and host conditions.','Restrict unnecessary PKI-object delegation to the approved template/CA management role and preserve intended enrollment.','Rescan directory and supplied service evidence and verify approved enrollment/renewal workflows after a reviewed change.','Do not equate directory full control, owner rights or an enrollment-related mask with successful issuance or complete ESC/GoldenCert support.');
const OBJECT_HELP = {users:'A user or service identity. Its groups, permissions and sessions help explain its access.',groups:'A collection of principals used to assign permissions. Some groups are privileged; membership alone can be expected.',computers:'A computer account. Endpoint groups, delegation and logged-on users can create additional access relationships.',domains:'An Active Directory domain and its security boundary. Domain-root permissions can have broad consequences.',ous:'A directory container used to organize objects and scope delegation or policy.',gpos:'A Group Policy object containing settings that can apply to users and computers.',certtemplates:'A certificate issuance template. Its flags and permissions must be assessed together with the issuing authority.',enterprisecas:'An enterprise certificate authority that can publish templates and issue certificates.',trusts:'A trust inventory object describing a relationship with another domain.'};
function helpText(tag,text,cls) {const e=document.createElement(tag); e.textContent=text;if(cls)e.className=cls;return e;}
function activateHelper(title){const panel=document.getElementById('helper');panel.classList.add('active');document.getElementById('toggleHelper').textContent='Hide details';document.getElementById('helperTitle').textContent=title;const content=document.getElementById('helperContent');content.replaceChildren();document.getElementById('helpMatches').replaceChildren();if(matchMedia('(max-width:850px)').matches)panel.scrollIntoView({block:'start',behavior:'smooth'});return content;}
function helpSection(root,title,text){root.append(helpText('h3',title),helpText('p',text));}
function explainDerivation(edge,root){
 if(!edge.Evidence)return;let evidence;try{evidence=typeof edge.Evidence==='string'?JSON.parse(edge.Evidence):edge.Evidence;}catch{return;}
 if(['OwnershipControlV1','OwnershipLegacyV1'].includes(evidence?.Derivation)){
  helpSection(root,'Ownership assessment',`${evidence.Assessment}: ${evidence.Reason}`);
  helpSection(root,'Policy and verification',`Mode: ${evidence.OwnerPolicyMode||'not captured'}. ${evidence.PolicySource||'Legacy collection'}. Effective access and server enforcement were not verified.`);return;
 }
 if(edge.ty==='GPLink'&&evidence?.GpoLinkMetadataVersion==='1'){
  helpSection(root,'Recorded link options',`Enabled: ${evidence.Enabled===true}. Enforced: ${evidence.Enforced===true}. Options: ${evidence.LinkOptions}. This is link configuration, not proof of policy application.`);
  if(evidence.GpoLinkEvidenceConflict)helpSection(root,'Conflicting snapshots','Automatic GPO scope inference was suppressed for this link.');return;
 }
 if(evidence?.Derivation==='GpoComputerScopeV1'){
  helpSection(root,'How this scope was derived',`Link root: ${evidence.LinkRoot}. Enforced: ${evidence.Enforced===true}. Computer policy only; this is not verified resultant policy.`);
  for(const [key,title] of [['ContainmentChain','Containment witness'],['ReadMembership','Read permission witness'],['ApplyMembership','Apply permission witness']])helpSection(root,title,(evidence[key]||[]).join(' → '));
  helpSection(root,'Unverified prerequisites','SYSVOL edit access, policy contents, client processing and actual effective access were not tested. Everyone and Authenticated Users are implicit computer-token identities; other membership witnesses use collected security-enabled groups.');return;
 }
 if(evidence?.Derivation==='AdcsEsc1DirectRootV1'){
  helpSection(root,'How this relationship was derived',evidence.EvidenceNote);if(evidence.PostExportGroupClassification)helpSection(root,'Conditional mixed-time candidate','Group classification was read after export; original permissions and memberships were not revalidated. Confirm a consistent current snapshot before treating the chain as current effective access.');
  for(const key of ['Template','EnterpriseCA','RootCA','NTAuthStore','HostingComputer','CertThumbprint','TemplateGrant','CAServiceGrant'])if(evidence[key])helpSection(root,key,evidence[key]);
  for(const key of ['TemplateMembership','CAServiceMembership'])if(Array.isArray(evidence[key]))helpSection(root,key,evidence[key].slice(0,64).map(String).join(' → '));
  return;
 } if(!evidence||evidence.Derivation!=='DCSyncMembershipIntersectionV1')return;
 helpSection(root,'How this relationship was derived','Both replication permissions reach the same principal on this domain through recorded security-group memberships. This is an inferred candidate; effective access has not been verified.');
 for(const [key,title] of [['GetChangesMembership','GetChanges membership witness'],['GetChangesAllMembership','GetChangesAll membership witness']])if(Array.isArray(evidence[key]))helpSection(root,title,evidence[key].slice(0,64).map(String).join(' → '));
 if(evidence.WitnessLimited)helpSection(root,'Witness display limit','A membership witness exceeds the 64-object evidence preview. Inspect the full membership graph before acting.');
}
function explainRelationship(edge){let h=HELP[edge.ty];if(h&&ownershipProof(edge)?.Assessment==='Suppressed projection')h={...h,title:'Ownership observation: projection suppressed',impact:'This observation is not included in the control-path graph. Suppression is not proof that all possible permissions are denied.',category:'context'};const root=activateHelper(h?.title || edge.ty);root.append(helpText('span',edge.ty,'pill '+(h?.category==='context'?'good':'warn')));const context=helpText('div','', 'context');context.append(helpText('p',(edge.sn||edge.s||'Source')+' → '+(edge.tn||edge.t||'Target')),helpText('p',(edge.s||'')+' → '+(edge.t||''),'identity'));root.append(context);
 explainDerivation(edge,root);
 if(!h){helpSection(root,'What is known','This relationship type appears in the supplied dataset. No built-in interpretation is available.');helpSection(root,'What to check','Inspect its source dataset and collector documentation. No risk classification has been inferred.');return;}
 const contextHelp=relationshipContext(edge);helpSection(root,'What does it mean?',relationshipMeaning(edge));helpSection(root,'Why is this shown?',h.why+' It is included as a '+(h.category==='context'?'context or inventory fact.':'permission or access capability worth reviewing.')+(DATA.HighValueNodes.some(n=>n.Id.toLowerCase()===(edge.t||'').toLowerCase())?' The target matches a recognized privileged-group SID.':''));helpSection(root,'Why could it matter?',h.impact);if(contextHelp)helpSection(root,'Prerequisites to verify',contextHelp.prerequisites);helpSection(root,'What should I check?',h.check);helpSection(root,'What this does not prove',h.caveat);
 if(typeof showFixPlan==='function')showFixPlan(edge,root);
 const link=document.createElement('a');link.href='https://bloodhound.specterops.io/resources/edges';link.target='_blank';link.rel='noopener noreferrer';link.textContent='BloodHound relationship reference ↗';root.append(helpText('hr',''),link);}
function explainNode(node){const root=activateHelper(node.n||node.i);root.append(helpText('span',node.t,'pill'),helpText('p',node.i,'identity'));helpSection(root,'What is this?',OBJECT_HELP[node.t]||'An object or identity referenced by the supplied directory data.');const kindTopic=HELP_TOPICS.find(t=>(t.Kinds||[]).includes(node.t));if(kindTopic)for(const section of kindTopic.Sections||[])helpSection(root,section.Title,section.Text);const target=DATA.HighValueNodes.some(h=>h.Id.toLowerCase()===node.i.toLowerCase());helpSection(root,'Why is it shown?',target?'Its SID matches a built-in privileged-group pattern. It is used as a target for the bounded path preview.':'It appears in the object search, permissions sample or bounded path preview. This alone does not flag it as unsafe.');if(typeof addObjectEvidence==='function')addObjectEvidence(node,root);const connections=reviewEdges.filter(e=>e.s.toLowerCase()===node.i.toLowerCase()||e.t.toLowerCase()===node.i.toLowerCase());helpSection(root,'Recorded connections in this preview',connections.length?connections.length+' relationships available here. Select one to understand the direction and meaning.':'No connections are included for this object in the HTML sample. Search the full index in Path Explorer for its other relationships.');for(const e of connections.slice(0,24)){const b=helpText('button',e.ty+' · '+(e.s===node.i?(e.tn||e.t):(e.sn||e.s)),'help-choice');b.type='button';b.addEventListener('click',()=>explainRelationship(e));root.append(b);}if(connections.length>24)root.append(helpText('p','Showing the first 24 connections. Use Path Explorer for the full graph.','note'));window.dispatchEvent(new CustomEvent('bh-select-node',{detail:node.i}));}
function explainCoverage(){const root=activateHelper('Understand collection coverage');helpSection(root,'What is this?','Coverage tells you which data was available when the report was built. Missing data can hide relationships and break paths.');helpSection(root,'Why is it shown?','A skipped endpoint phase, unreadable security descriptor, unresolved identity or failed host reduces what the report can establish.');for(const note of DATA.CoverageNotes||[])root.append(helpText('p',note,'context'));helpSection(root,'What should I check?','Read scan-metadata.json and endpoint-status files. Collect the missing scope or correct access failures, then generate the report again.');helpSection(root,'What this does not prove','An empty path or a missing finding is not proof that the environment has no exposure.');}
let reviewEdges=[];
function initializeAdcsGaps(){
 const summary=document.getElementById('adcsGapSummary'),body=document.getElementById('adcsGapRows');if(!summary||!body)return;
 body.replaceChildren();const data=DATA.AdcsGaps;
 if(!data){summary.textContent='Prerequisite diagnostics were not recorded in this report. Rebuild with the current application.';return;}
 summary.textContent=`${fmt(data.Total)} recorded prerequisite gaps; showing up to ${fmt(data.Limit)}. These explain supported candidate combinations that could not be established. They are not exhaustive proof of why any arbitrary path is absent. Successful and suppressed combinations can coexist.`;
 for(const item of data.Rows||[]){const row=document.createElement('tr');for(const text of [item[4]||item[0],item[5]||item[1],item[2],item[3]])row.append(helpText('td',text));body.append(row);}
 if(!data.Total){const row=document.createElement('tr'),cell=helpText('td','No prerequisite gaps were recorded by the supported AD CS analysis. This does not prove complete coverage or absence of exposure.');cell.colSpan=4;row.append(cell);body.append(row);}
}
function initializeAdcsReview(){
 initializeAdcsGaps();
 const review=DATA.AdcsReview;
 const summary=document.getElementById('adcsSummary'),body=document.getElementById('adcsRows');
 if(!summary||!body)return;
 body.replaceChildren();
 if(!review){summary.textContent='Template review was not available when this report was generated. Rebuild the report with the current application.';return;}
 summary.textContent=`${fmt(review.Total)} templates; ${fmt(review.Matched)} match template conditions; ${fmt(review.Incomplete)} have incomplete metadata; ${fmt(review.Conflicting)} have conflicting snapshots. ${review.Note} ${DATA.AdcsScope||''}${review.Truncated?' Showing the first 100 templates; this preview is incomplete.':''}`;
 if(!review.Total){const row=document.createElement('tr'),cell=document.createElement('td');cell.colSpan=3;cell.textContent='No certificate template objects were supplied. AD CS exposure was not evaluated.';row.append(cell);body.append(row);}
 for(const item of review.Rows||[]){const row=document.createElement('tr');for(const value of [item.Name||item.Id,item.Status,item.Checks]){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}body.append(row);}
}
function initializeReport(){
 initializeAdcsReview();
 const nc=DATA.NodeCounts,ec=DATA.EdgeCounts;const total=Object.values(nc).reduce((a,b)=>a+Number(b),0);const cards=[['Directory objects',total],['Users',nc.users],['Computers',nc.computers],['Groups',nc.groups],['Permission grants',ec.acl],['Access relationships',ec.access],['Privileged groups',DATA.HighValueNodes.length],['Coverage notes',DATA.CoverageNotes?.length||0]];
 document.getElementById('summaryCards').innerHTML=cards.map(([label,value])=>`<div class="card"><div class="n">${fmt(value)}</div><div class="l">${label}</div></div>`).join('');
 document.getElementById('coverageBanner').textContent=DATA.CoverageNotes?.length?`${fmt(DATA.CoverageNotes.length)} collection or analysis notes need context. Review collection coverage before drawing conclusions.`:'This is a point-in-time review of the supplied data. Check collection scope and permissions before drawing conclusions.';
 const nodes=new Map(DATA.Ego.Nodes.map(n=>[n.i,n]));for(const n of DATA.SearchIndex)if(!nodes.has(n.i))nodes.set(n.i,n);
 const seen=new Set();for(const raw of [...(DATA.ReviewRelationships||[]),...DATA.Ego.Edges]){const key=JSON.stringify([raw.s,raw.t,raw.ty]);if(seen.has(key))continue;seen.add(key);reviewEdges.push({...raw,sn:raw.sn||nodes.get(raw.s)?.n||raw.s,tn:raw.tn||nodes.get(raw.t)?.n||raw.t});}
 reviewEdges.sort((a,b)=>(HELP[a.ty]?.category==='context'?1:0)-(HELP[b.ty]?.category==='context'?1:0)||a.ty.localeCompare(b.ty));
 const renderReview=()=>{const q=document.getElementById('reviewSearch').value.toLowerCase(),category=document.getElementById('reviewFilter').value;const hits=reviewEdges.filter(e=>(category==='all'||(HELP[e.ty]?.category||'context')===category)&&[e.sn,e.tn,e.ty,e.s,e.t].some(v=>String(v).toLowerCase().includes(q)));const tbody=document.querySelector('#reviewTable tbody');tbody.replaceChildren();document.getElementById('reviewCount').textContent=`${fmt(hits.length)} matching relationships in this sample · showing up to 100`;for(const edge of hits.slice(0,100)){const row=document.createElement('tr');const known=HELP[edge.ty];const context=!known||known.category==='context';const first=document.createElement('td');first.append(helpText('span',context?'Context':'Review first','pill '+(context?'good':'warn')));row.append(first);row.append(helpText('td',edge.sn+' → '+edge.tn),helpText('td',edge.ty));const cell=document.createElement('td'),button=helpText('button','Explain');button.addEventListener('click',()=>{tbody.querySelectorAll('.selected-row').forEach(r=>r.classList.remove('selected-row'));row.classList.add('selected-row');explainRelationship(edge);});cell.append(button);row.append(cell);tbody.append(row);}if(!hits.length){const row=document.createElement('tr'),cell=helpText('td','No matching relationships in this sample. Search the full graph in Path Explorer.','empty');cell.colSpan=3;row.append(cell);tbody.append(row);}};
 document.getElementById('reviewSearch').addEventListener('input',renderReview);document.getElementById('reviewFilter').addEventListener('change',renderReview);renderReview();
 const hv=document.getElementById('hvList');if(!DATA.HighValueNodes.length)hv.append(helpText('p','No recognized privileged group SIDs are included. Check collection scope.','note'));for(const h of DATA.HighValueNodes){const button=helpText('button',h.Name,'pill danger');button.addEventListener('click',()=>explainNode({i:h.Id,n:h.Name,t:h.Type}));hv.append(button);}
 const acl=document.querySelector('#aclTable tbody');for(const r of DATA.TopAclHolders){const row=document.createElement('tr');row.append(helpText('td',r.Name),helpText('td',r.Type),helpText('td',fmt(r.OutDegree)));const cell=document.createElement('td'),b=helpText('button','Inspect');b.addEventListener('click',()=>explainNode({i:r.Id,n:r.Name,t:r.Type}));cell.append(b);row.append(cell);acl.append(row);}if(!DATA.TopAclHolders.length){const row=document.createElement('tr'),cell=helpText('td','No ACL grants are included in this dataset.','empty');cell.colSpan=3;row.append(cell);acl.append(row);}
 document.getElementById('searchNote').textContent=DATA.SearchIndexTruncated?`Search a sample of ${fmt(DATA.SearchIndex.length)} objects. Use Path Explorer to search the full dataset.`:`${fmt(DATA.SearchIndex.length)} objects available here. Enter at least two characters.`;
 document.getElementById('searchBox').addEventListener('input',event=>{const q=event.target.value.trim().toLowerCase(),body=document.querySelector('#searchTable tbody');body.replaceChildren();if(q.length<2)return;const hits=DATA.SearchIndex.filter(r=>(r.n||'').toLowerCase().includes(q)||r.i.toLowerCase().includes(q)).slice(0,100);for(const n of hits){const row=document.createElement('tr');row.append(helpText('td',n.n),helpText('td',n.t),helpText('td',n.i));const cell=document.createElement('td'),b=helpText('button','Inspect');b.addEventListener('click',()=>explainNode(n));cell.append(b);row.append(cell);body.append(row);}if(!hits.length){const row=document.createElement('tr'),cell=helpText('td','No matches in this HTML sample. Try the full index in Path Explorer.','empty');cell.colSpan=3;row.append(cell);body.append(row);}});
 const helpSearch=document.getElementById('helpSearch');helpSearch.addEventListener('input',()=>{const q=helpSearch.value.trim(),results=document.getElementById('helpMatches');results.replaceChildren();if(!q)return;const matches=searchHelp(q);results.append(helpText('p',matches.length+' matching help entries · showing up to 16','note'));for(const entry of matches.slice(0,16)){const b=helpText('button',entry.label,'help-choice');b.addEventListener('click',()=>{helpSearch.value='';if(entry.topic)explainHelpTopic(entry.topic);else{explainRelationship({ty:entry.type,sn:'Source principal',tn:'Target object'});document.getElementById('helperContent').append(helpText('p','General reference only: this entry is not evidence that the relationship was collected.','note'));}});results.append(b);}if(!matches.length)results.append(helpText('p','No matching help. Try a relationship, property such as SecurityEnabled, or a task such as routes or import.','note'));});
 document.getElementById('openGuide').addEventListener('click',()=>{document.getElementById('helper').classList.add('active');document.getElementById('toggleHelper').textContent='Hide details';helpSearch.focus();document.getElementById('helper').scrollIntoView({block:'nearest',behavior:'smooth'});});document.getElementById('toggleHelper').addEventListener('click',()=>{const panel=document.getElementById('helper');panel.classList.toggle('active');document.getElementById('toggleHelper').textContent=panel.classList.contains('active')?'Hide details':'Show details';});document.getElementById('printReport').addEventListener('click',()=>window.print());document.getElementById('explainCoverage').addEventListener('click',explainCoverage);document.getElementById('explainTargets').addEventListener('click',()=>{const root=activateHelper('Why these groups?');helpSection(root,'How targets are selected','Tessera recognizes privileged Windows and domain group SIDs, such as Domain Admins and built-in Administrators. Names can change; the SID pattern is used for selection.');helpSection(root,'What the graph means','The preview follows recorded incoming ACL, access and membership relationships for up to four hops. It is limited in size.');helpSection(root,'What to verify','Custom privileged groups may not match these built-in patterns. Search your own targets in Path Explorer. A path expresses recorded relationships, not proof that every step will succeed.');});
}
